<script setup lang="ts">
definePageMeta({layout:'admin',middleware:'admin-auth'})
type Row={article:any;helpful:number;notHelpful:number;total:number;helpfulRatio:number};const {show}=useAdminToast();const rows=ref<Row[]>([]),detail=ref<any|null>(null),search=ref(''),city=ref(''),category=ref(''),sort=ref('needs'),page=ref(1),total=ref(0),pageCount=ref(0),pending=ref(false),toast=ref(''),summary=reactive({helpful:0,notHelpful:0,total:0,helpfulRatio:null as number|null});const cats=['Ibadah','Panduan','Kehidupan','Sosial','Ekonomi','Bisnis','Kuliner','Transportasi','Akomodasi','Makkah','Madinah','Budaya','Sejarah','Berita / Update'];const date=(v:string|null)=>v?new Date(v).toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'}):'—';const signal=(r:Row)=>!r.total?'Belum ada feedback':r.notHelpful>=3||r.helpfulRatio<70?'Perlu Perhatian':r.helpfulRatio<90?'Perlu Dipantau':'Baik';const signalClass=(r:Row)=>!r.total?'bg-neutral-soft text-neutral-charcoal/60':r.notHelpful>=3||r.helpfulRatio<70?'bg-red-50 text-red-700':r.helpfulRatio<90?'bg-gold-sand text-neutral-charcoal':'bg-brand-green/10 text-brand-green'
async function load(){pending.value=true;try{const r=await $fetch<any>('/api/admin/media/article-feedback',{query:{search:search.value||undefined,city:city.value||undefined,category:category.value||undefined,sort:sort.value,page:page.value,pageSize:10}});rows.value=r.data;total.value=r.meta.total;pageCount.value=r.meta.pageCount;Object.assign(summary,r.summary)}catch(e:any){show(e.data?.statusMessage||'Feedback gagal dimuat.','error')}finally{pending.value=false}}async function open(r:Row){try{detail.value=(await $fetch<any>(`/api/admin/media/article-feedback/${r.article.id}`)).data}catch(e:any){show(e.data?.statusMessage||'Detail gagal dimuat.','error')}}watch([search,city,category,sort],()=>{page.value=1;load()});onMounted(load)
</script>
<template><div><PageHead title="Feedback Artikel" subtitle="Media · Interaksi"><template #actions><span class="rounded-full border border-gold-soft bg-gold-sand px-3 py-1.5 text-xs font-semibold">EDITORIAL ANALYTICS</span></template></PageHead><section class="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div class="rounded-2xl border border-neutral-line bg-neutral-soft p-5"><p class="text-xs font-semibold uppercase tracking-wider text-neutral-charcoal/50">Total Feedback</p><p class="mt-2 text-3xl font-heading font-semibold">{{summary.total}}</p></div><div class="rounded-2xl border border-brand-green/15 bg-brand-green/5 p-5"><p class="text-xs font-semibold uppercase tracking-wider text-brand-green/70">Membantu</p><p class="mt-2 text-3xl font-heading font-semibold text-brand-green">{{summary.helpful}}</p></div><div class="rounded-2xl border border-red-100 bg-red-50/60 p-5"><p class="text-xs font-semibold uppercase tracking-wider text-red-700/70">Kurang Membantu</p><p class="mt-2 text-3xl font-heading font-semibold text-red-700">{{summary.notHelpful}}</p></div><div class="rounded-2xl border border-gold-soft bg-gold-sand/50 p-5"><p class="text-xs font-semibold uppercase tracking-wider text-neutral-charcoal/55">Helpful Rate</p><p class="mt-2 text-3xl font-heading font-semibold">{{summary.helpfulRatio===null?'—':`${summary.helpfulRatio}%`}}</p></div></section><section class="mt-6 rounded-2xl border border-neutral-line bg-white p-5"><div class="grid gap-3 lg:grid-cols-[minmax(0,1fr)_170px_190px_210px] lg:items-center"><input v-model="search" placeholder="Cari judul artikel..." class="min-h-[42px] rounded-xl border border-neutral-line px-3 text-sm"/><select v-model="city" class="min-h-[42px] rounded-xl border border-neutral-line px-3 text-sm"><option value="">Semua city</option><option>GENERAL</option><option>MAKKAH</option><option>MADINAH</option></select><select v-model="category" class="min-h-[42px] rounded-xl border border-neutral-line px-3 text-sm"><option value="">Semua kategori</option><option v-for="x in cats">{{x}}</option></select><select v-model="sort" class="min-h-[42px] rounded-xl border border-neutral-line px-3 text-sm"><option value="needs">Perlu perhatian</option><option value="total">Total feedback</option><option value="helpful">Helpful terbanyak</option><option value="notHelpful">Not helpful terbanyak</option><option value="ratio">Helpful rate</option></select></div></section><section class="mt-6 overflow-x-auto rounded-2xl border border-neutral-line bg-white p-5"><div class="flex items-center justify-between"><h2 class="font-heading text-lg font-semibold">Performa Artikel</h2><span class="text-xs text-neutral-charcoal/50">{{total}} artikel</span></div><table class="mt-4 w-full min-w-[900px] table-fixed text-left text-sm"><thead class="border-b text-xs uppercase tracking-wider text-neutral-charcoal/50"><tr><th class="w-[30%] pb-3">Artikel</th><th class="w-[12%]">City</th><th class="w-[15%]">Kategori</th><th class="w-[9%] text-right">Membantu</th><th class="w-[10%] text-right">Kurang</th><th class="w-[8%] text-right">Total</th><th class="w-[12%] text-right">Helpful Rate</th><th class="w-[14%] pl-5">Signal</th></tr></thead><tbody><tr v-for="r in rows" :key="r.article.id" class="cursor-pointer border-b last:border-0 hover:bg-gold-sand/20" @click="open(r)"><td class="py-4 pr-4"><b class="block break-words">{{r.article.title}}</b><small class="text-neutral-charcoal/50">Published {{date(r.article.publishedAt)}} · Updated {{date(r.article.updatedAt)}}</small></td><td>{{r.article.city}}</td><td>{{r.article.category}}</td><td class="text-right font-semibold text-brand-green">{{r.helpful}}</td><td class="text-right font-semibold" :class="r.notHelpful?'text-red-700':''">{{r.notHelpful}}</td><td class="text-right">{{r.total}}</td><td class="text-right"><span v-if="r.total" class="font-semibold">{{r.helpfulRatio}}%</span><span v-else class="text-neutral-charcoal/45">—</span></td><td class="pl-5"><span class="inline-flex rounded-full px-2.5 py-1 text-[11px] font-semibold" :class="signalClass(r)">{{signal(r)}}</span></td></tr></tbody></table><p v-if="!pending&&!rows.length" class="py-12 text-center text-sm">Belum ada artikel.</p><div v-if="pageCount>1" class="mt-4 flex gap-2 border-t pt-4"><button class="rounded-full border px-3 py-1 text-xs" :disabled="page===1" @click="page--;load()">Previous</button><button v-for="n in pageCount" :key="n" class="rounded-full border px-2 py-1 text-xs" :class="n===page?'bg-brand-green text-white':''" @click="page=n;load()">{{n}}</button><button class="rounded-full border px-3 py-1 text-xs" :disabled="page===pageCount" @click="page++;load()">Next</button></div></section><div v-if="detail" class="fixed inset-0 z-50 flex items-center justify-center bg-neutral-charcoal/40 p-5" role="dialog" aria-modal="true" @click.self="detail=null"><section class="w-full max-w-lg rounded-2xl border border-neutral-line bg-white p-6 shadow-xl"><div class="flex items-start justify-between gap-4"><div><p class="text-xs font-semibold uppercase tracking-wider text-gold">Feedback Artikel</p><h2 class="mt-2 font-heading text-xl font-semibold">{{detail.article.title}}</h2></div><button class="text-2xl leading-none text-neutral-charcoal/50" aria-label="Tutup" @click="detail=null">×</button></div><div class="mt-6 grid grid-cols-4 gap-2 text-center"><div class="rounded-xl bg-neutral-soft p-3"><b class="block text-xl">{{detail.total}}</b><small>Total</small></div><div class="rounded-xl bg-brand-green/10 p-3"><b class="block text-xl text-brand-green">{{detail.helpful}}</b><small>Membantu</small></div><div class="rounded-xl bg-red-50 p-3"><b class="block text-xl text-red-700">{{detail.notHelpful}}</b><small>Kurang</small></div><div class="rounded-xl bg-gold-sand p-3"><b class="block text-xl">{{detail.total?Math.round(detail.helpful/detail.total*1000)/10+'%':'—'}}</b><small>Rate</small></div></div><p class="mt-5 text-sm text-neutral-charcoal/60">Feedback ditampilkan sebagai sinyal agregat editorial. Tidak ada data identitas pengguna.</p></section></div></div></template>
